mapper.select:
SELECT id AS internal_id, public_id AS id, client_run_id, title, started_at, ended_at, duration_seconds, distance_meters, average_pace_seconds_per_km, route_point_count FROM runs WHERE user_id = #{userId} AND deleted_at IS NULL
AND (started_at, id) < (#{afterStart}, #{afterId})
ORDER BY started_at DESC, id DESC LIMIT #{limit}
